class InvalidFinalForkDecisionAggregateChainError(ValueError):
    """A final fork decision aggregate chain successor breaks its
    contract."""


def _ffdac_invalid(
    message: str,
) -> InvalidFinalForkDecisionAggregateChainError:
    return InvalidFinalForkDecisionAggregateChainError(
        f"invalid final fork decision aggregate chain: {message}"
    )


def _reject_duplicate_ffdac_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate successor keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _ffdac_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


# -- Stage views over a root decision aggregate or a successor packet ----------

def _ffdac_root_view(raw: bytes) -> dict:
    """Structurally parse a root final decision aggregate predecessor."""
    payload, _signature = _parse_facfda(raw)
    return {
        "kind": "root",
        _FFDAC_ROOT_DIGEST: hashlib.sha256(raw).hexdigest(),
        _FFDAC_HEIGHT: 0,
        STATUS: payload[STATUS],
        _FACFDA_DECLARATION: payload[_FACFDA_DECLARATION],
        _FACFDA_INPUTS: list(payload[_FACFDA_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[ITEMS]),
        "prune_policy_digest": payload[_FACFDA_PRUNE_POLICY_DIGEST],
        "authorization_policy_digest": payload[
            _FACFDA_AUTHORIZATION_POLICY_DIGEST
        ],
        "site_policy_digest": payload[_FACFDA_SITE_POLICY_DIGEST],
        "signer_site_policy_digest": payload[
            _FACFDA_SIGNER_SITE_POLICY_DIGEST
        ],
        "adjudication_site_policy_digest": payload[
            _FACFDA_ADJUDICATION_SITE_POLICY_DIGEST
        ],
        "policy_digest": payload[_FACFDA_DECISION_SITE_POLICY_DIGEST],
        _FFDAC_POLICY_VERSION:
            FINAL_AGGREGATE_CHAIN_FORK_DECISION_AGGREGATE_VERSION,
        _FFDAC_EFFECTIVE_AT: None,
    }


def _ffdac_successor_view(raw: bytes) -> dict:
    """Structurally parse a final decision aggregate successor predecessor."""
    payload, _signature, _increment = _ffdac_parse_successor(raw)
    return {
        "kind": "successor",
        _FFDAC_ROOT_DIGEST: payload[_FFDAC_ROOT_DIGEST],
        _FFDAC_HEIGHT: payload[_FFDAC_HEIGHT],
        STATUS: payload[STATUS],
        _FACFDA_DECLARATION: copy.deepcopy(payload[_FACFDA_DECLARATION]),
        _FACFDA_INPUTS: list(payload[_FACFDA_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[ITEMS]),
        "prune_policy_digest": payload[_FACFDA_PRUNE_POLICY_DIGEST],
        "authorization_policy_digest": payload[
            _FACFDA_AUTHORIZATION_POLICY_DIGEST
        ],
        "site_policy_digest": payload[_FACFDA_SITE_POLICY_DIGEST],
        "signer_site_policy_digest": payload[
            _FACFDA_SIGNER_SITE_POLICY_DIGEST
        ],
        "adjudication_site_policy_digest": payload[
            _FACFDA_ADJUDICATION_SITE_POLICY_DIGEST
        ],
        "policy_digest": payload[_FFDAC_NEW_POLICY_DIGEST],
        _FFDAC_POLICY_VERSION: payload[_FFDAC_POLICY_VERSION],
        _FFDAC_EFFECTIVE_AT: payload[_FFDAC_EFFECTIVE_AT],
    }


def _ffdac_predecessor_view(raw: object) -> dict:
    """Parse predecessor bytes (root aggregate or successor packet).

    The packet kind is chosen from the payload key set so a malformed
    root raises
    :class:`InvalidFinalAggregateChainForkDecisionAggregateError` while a
    malformed successor raises
    :class:`InvalidFinalForkDecisionAggregateChainError`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("predecessor must be bytes")
    keys = _packet_payload_keys(raw)
    if keys is not None and _FFDAC_ROOT_DIGEST in keys:
        return _ffdac_successor_view(raw)
    return _ffdac_root_view(raw)


# -- Recomputing one stage verdict from prefix plus decision increment ---------

def _ffdac_recompute(
    prefix_inputs: list[str],
    prefix_rows: list[dict],
    increment: list[dict],
    prune_policy_digest: str,
    authorization_policy_digest: str,
    site_policy_digest: str,
    signer_site_policy_digest: str,
    adjudication_site_policy_digest: str,
    fork_threshold: int,
    decision_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Recompute the complete stage conclusion from prefix plus increment.

    Unlike the lower chain layers, every decision of the full stage --
    the whole prefix as well as this hop's increment -- is re-verified,
    authenticated and authorized at ``moment`` under the hop's decision
    site policy, so a later credential expiry or policy change rejects
    the whole hop with no grandfathering.  The prefix statements then
    win over any freshly repeated decision during the stage tally.
    """
    increment_rows: list[dict] = []
    increment_digests: list[str] = []
    for item in increment:
        raw = item[_FFDAC_PACKET]
        increment_digests.append(hashlib.sha256(raw).hexdigest())
        increment_rows.append(
            _aggregate_facfda_one(
                item,
                prune_policy_digest,
                authorization_policy_digest,
                site_policy_digest,
                signer_site_policy_digest,
                adjudication_site_policy_digest,
                fork_threshold,
                decision_site_policy,
                validated_keyring,
                moment,
            )
        )

    # Re-verify every prefix statement at this hop's moment and policy
    # from its bound authenticated row (credential window, exact
    # identity/version authorization and the declaration's own tally).
    prefix_rows_verified = _ffdac_reverify_rows(
        prefix_rows,
        fork_threshold,
        decision_site_policy,
        validated_keyring,
        moment,
    )

    full_inputs = list(prefix_inputs) + increment_digests
    working_rows = copy.deepcopy(prefix_rows_verified)
    working_rows.extend(copy.deepcopy(increment_rows))
    status, declaration = _cfca_tally_chain_rows(
        working_rows, len(prefix_rows_verified),
        decision_site_policy[ADJ_THRESHOLD],
    )
    return {
        _FACFDA_INPUTS: full_inputs,
        PA_ITEMS: _pac_sort_rows(working_rows),
        STATUS: status,
        _FACFDA_DECLARATION: declaration,
    }


def _ffdac_reverify_rows(
    prefix_rows: list[dict],
    fork_threshold: int,
    decision_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> list[dict]:
    """Re-derive each prefix row purely from its bound authenticated data.

    The prefix packets were all individually re-verified when their hop
    was sealed; here each bound row is re-checked at the new moment from
    its own authenticated conclusion.  Structurally rejected rows and
    non-counted rows (``unauthenticated``/``unauthorized``, which carry
    no declaration and cast no vote) keep their bound conclusion; a
    counted row (``valid``, ``duplicate`` or ``contradiction``) has its
    credential window re-checked against the keyring, its exact identity
    and key version re-authorized against the hop's decision site
    policy, and its complete declaration re-tallied through the final
    decision rules.  Any failure of a previously counted row raises
    :class:`InvalidFinalForkDecisionAggregateChainError`.
    """
    verified: list[dict] = []
    for row in prefix_rows:
        if row[_FACFDA_DECLARATION] is None:
            verified.append(copy.deepcopy(row))
            continue
        site = row[VD_ISSUER]
        key_version = row[KEY_VERSION]
        key_entry = None
        for candidate in validated_keyring.get(site, ()):
            if candidate[VERSION] == key_version:
                key_entry = candidate
                break
        if key_entry is None or key_entry[REVOKED]:
            raise AuthenticationError(
                f"prefix decision from {site!r} version {key_version} is no "
                "longer usable at this hop's moment"
            )
        if moment < key_entry[NOT_BEFORE] or moment > key_entry[NOT_AFTER]:
            raise AuthenticationError(
                f"prefix decision from {site!r} version {key_version} is not "
                "usable at this hop's moment"
            )
        allowed_versions = decision_site_policy[ADJ_SITES].get(site)
        if allowed_versions is None or key_version not in allowed_versions:
            raise _ffdac_invalid(
                f"prefix decision from {site!r} version {key_version} is no "
                "longer authorized by the hop decision site policy"
            )
        declaration = row[_FACFDA_DECLARATION]
        if declaration is not None:
            _reconcile_facfda_declaration(
                declaration, fork_threshold,
                f"prefix item {row[ID]!r} declaration",
            )
        verified.append(copy.deepcopy(row))
    return verified


def _ffdac_assert_extends(
    previous: dict, full_inputs: list[str], increment: list[dict],
    unchanged: bool,
) -> None:
    """Enforce the append-only decision prefix and disjoint identities.

    The predecessor's decision digests must remain the ordered prefix of
    the stage -- nothing is deleted, changed or reordered -- and a
    non-empty increment adds only new packet digests and new item ids.
    An unchanged policy must add at least one decision; a rotation may
    re-seal the identical sequence with an empty increment.
    """
    prefix_inputs = previous[_FACFDA_INPUTS]
    if unchanged and not increment:
        raise _ffdac_invalid("an unchanged policy requires new decisions")
    if len(full_inputs) < len(prefix_inputs):
        raise _ffdac_invalid(
            "the decision sequence must extend the predecessor"
        )
    if full_inputs[:len(prefix_inputs)] != prefix_inputs:
        raise _ffdac_invalid(
            "the decision sequence must keep the predecessor as an ordered "
            "prefix; history must not be deleted, changed or reordered"
        )
    prefix_digests = set(prefix_inputs)
    prefix_ids = {row[ID] for row in previous[PA_ITEMS]}
    seen_digests: set[str] = set()
    seen_ids: set[str] = set()
    for item in increment:
        digest = hashlib.sha256(item[_FFDAC_PACKET]).hexdigest()
        if digest in prefix_digests or digest in seen_digests:
            raise _ffdac_invalid(
                "a decision packet already in the prefix must not be "
                "appended again"
            )
        seen_digests.add(digest)
        item_id = item[ID]
        if item_id in prefix_ids or item_id in seen_ids:
            raise _ffdac_invalid(
                f"decision item id {item_id!r} is already part of the chain"
            )
        seen_ids.add(item_id)


def _ffdac_assert_transition(previous: dict, verdict: dict) -> None:
    """Enforce the per-hop verdict state machine.

    ``insufficient`` may gain supplemental decisions and become
    ``accepted`` or ``conflicted``; an ``accepted`` head only keeps the
    identical common declaration or advances to ``conflicted`` (it never
    falls back to insufficient or swaps declarations); a ``conflicted``
    verdict can never be masked by a later majority.
    """
    prev_status = previous[STATUS]
    new_status = verdict[STATUS]
    if prev_status == PA_STATUS_CONFLICTED:
        if new_status != PA_STATUS_CONFLICTED:
            raise _ffdac_invalid(
                "a conflicted aggregate can never be outvoted or fall back"
            )
    elif prev_status == PA_STATUS_ACCEPTED:
        if new_status == PA_STATUS_INSUFFICIENT:
            raise _ffdac_invalid(
                "an accepted aggregate must not fall back to insufficient"
            )
        if new_status == PA_STATUS_ACCEPTED:
            if verdict[_FACFDA_DECLARATION] != previous[_FACFDA_DECLARATION]:
                raise _ffdac_invalid(
                    "an accepted aggregate may only keep the same common "
                    "declaration"
                )


def _ffdac_assert_sealer_authorized(
    old_policy: dict, new_policy: dict, issuer: str, key_version: int
) -> None:
    """The successor sealer must be authorized under both site policies."""
    if key_version not in old_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _ffdac_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the previous site policy"
        )
    if key_version not in new_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _ffdac_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the rotated site policy"
        )


# -- Successor packet shape ----------------------------------------------------

def _ffdac_bound_decisions(raw_items: object, where: str) -> list[dict]:
    """Parse the raw decision increment bound inside a successor packet."""
    if not isinstance(raw_items, list):
        raise TypeError(f"{where} decisions must be a list")
    validated: list[dict] = []
    for position, item in enumerate(raw_items):
        item_where = f"{where} decision {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{item_where} must be an object")
        if set(item.keys()) != _FFDAC_DECISION_ITEM_KEYS:
            raise _ffdac_invalid(
                f"{item_where} must contain exactly the keys 'decision' and "
                "'id'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{item_where} id must be a str")
        if item_id == "":
            raise _ffdac_invalid(f"{item_where} id must be non-empty")
        packet_hex = item[_FFDAC_PACKET]
        if not isinstance(packet_hex, str):
            raise TypeError(f"{item_where} decision must be a str")
        try:
            packet = _hex_bytes(packet_hex)
        except ValueError as exc:
            raise _ffdac_invalid(
                f"{item_where} decision must be non-empty even-length "
                "lowercase hex"
            ) from exc
        validated.append({ID: item_id, _FFDAC_PACKET: packet})
    return validated


def _ffdac_validated_rows(raw_rows: object, where: str) -> list[dict]:
    """Validate the bound aggregate rows of a chain successor payload.

    The row contract is the one
    :func:`aggregate_final_aggregate_chain_fork_decisions` binds; a
    counted row's complete declaration keeps the term-by-term proof
    digest vector of a legal final aggregate chain fork decision and may
    carry the empty common fork edge set.  A wrong JSON type raises
    :class:`TypeError` and every other structural fault raises
    :class:`InvalidFinalForkDecisionAggregateChainError`.
    """
    if not isinstance(raw_rows, list):
        raise TypeError(f"{where} items must be a list")
    if not raw_rows:
        raise _ffdac_invalid(f"{where} items must be a non-empty list")
    parsed_rows: list[dict] = []
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        row_where = f"{where} item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be an object")
        if set(row.keys()) != _PFDA_ROW_KEYS:
            raise _ffdac_invalid(
                f"{row_where} must contain exactly the keys 'conclusion', "
                "'digest', 'id', 'issuer', 'keyVersion', 'reason' and "
                "'declaration'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{row_where} id must be a str")
        if row_id == "":
            raise _ffdac_invalid(f"{row_where} id must be non-empty")
        if row_id in seen_ids:
            raise _ffdac_invalid(f"{row_where} repeats an id")
        seen_ids.add(row_id)
        digest = row[CP_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{row_where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _ffdac_invalid(
                f"{row_where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None and not isinstance(site, str):
            raise TypeError(f"{row_where} issuer must be a str or null")
        if site == "":
            raise _ffdac_invalid(f"{row_where} issuer must be non-empty")
        key_version = row[KEY_VERSION]
        if isinstance(key_version, bool) or not isinstance(key_version, int):
            if key_version is not None:
                raise TypeError(
                    f"{row_where} keyVersion must be an int or null"
                )
        elif key_version <= 0:
            raise _ffdac_invalid(
                f"{row_where} keyVersion must be positive"
            )
        if (site is None) != (key_version is None):
            raise _ffdac_invalid(
                f"{row_where} issuer and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{row_where} conclusion must be a str")
        reason = row[ADJ_REASON]
        if conclusion == PA_CONCLUSION_VALID:
            if reason is not None:
                raise _ffdac_invalid(
                    f"{row_where} reason must be null for a valid row"
                )
        elif conclusion == PA_CONCLUSION_INVALID:
            if reason not in _PFDA_INVALID_REASONS:
                raise _ffdac_invalid(
                    f"{row_where} reason must be one of 'invalid', "
                    "'unauthenticated' or 'unauthorized'"
                )
        elif conclusion in (
            PA_CONCLUSION_DUPLICATE, PA_CONCLUSION_CONTRADICTION
        ):
            expected = (
                REASON_DUPLICATE
                if conclusion == PA_CONCLUSION_DUPLICATE
                else REASON_CONTRADICTION
            )
            if reason != expected:
                raise _ffdac_invalid(
                    f"{row_where} reason must match its conclusion"
                )
        else:
            raise _ffdac_invalid(f"{row_where} conclusion is not known")
        identity_present = reason != PA_CONCLUSION_INVALID
        if identity_present:
            if site is None:
                raise _ffdac_invalid(
                    f"{row_where} an authenticated or authorized row must "
                    "carry its issuer"
                )
        elif site is not None:
            raise _ffdac_invalid(
                f"{row_where} an invalid row must carry no issuer"
            )
        if conclusion == PA_CONCLUSION_INVALID:
            if row[_FACFDA_DECLARATION] is not None:
                raise _ffdac_invalid(
                    f"{row_where} an invalid row must carry no declaration"
                )
            declaration = None
        else:
            try:
                declaration = _validated_pfda_declaration(
                    row[_FACFDA_DECLARATION], f"{row_where} declaration",
                    invalid=_facfda_invalid, positional_proofs=True,
                    allow_empty_edges=True,
                )
            except InvalidFinalAggregateChainForkDecisionAggregateError \
                    as exc:
                raise _ffdac_invalid(str(exc)) from exc
            if declaration is None:
                raise _ffdac_invalid(
                    f"{row_where} a counted row must carry its declaration"
                )
        parsed_rows.append({
            ADJ_CONCLUSION: conclusion,
            CP_DIGEST: digest,
            ID: row_id,
            VD_ISSUER: site,
            KEY_VERSION: key_version,
            ADJ_REASON: reason,
            _FACFDA_DECLARATION: declaration,
        })
    return parsed_rows


def _ffdac_parse_successor(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate successor bytes into ``(payload, signature, increment)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, row or increment fault raises
    :class:`InvalidFinalForkDecisionAggregateChainError`.  The
    predecessor, policy, moment, tally and signature bindings are
    checked by the chain verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("successor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _ffdac_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _ffdac_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_ffdac_keys
        )
    except json.JSONDecodeError as exc:
        raise _ffdac_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("successor must be a JSON object")
    if set(data.keys()) != _FFDAC_TOP_KEYS:
        raise _ffdac_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("successor signature must be a str")
    if not _prune_is_digest(signature):
        raise _ffdac_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("successor payload must be an object")
    if set(payload.keys()) != _FFDAC_SUCCESSOR_PAYLOAD_KEYS:
        raise _ffdac_invalid("payload must contain exactly the bound keys")

    for key in (
        _FFDAC_ROOT_DIGEST, _FFDAC_PREDECESSOR_DIGEST,
        _FFDAC_OLD_POLICY_DIGEST, _FFDAC_NEW_POLICY_DIGEST,
    ) + _FFDAC_INVARIANT_DIGEST_FIELDS:
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _ffdac_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[_FFDAC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 1:
        raise _ffdac_invalid("payload height must be a positive integer")
    policy_version = payload[_FFDAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _ffdac_invalid("payload policyVersion must be positive")
    effective = payload[_FFDAC_EFFECTIVE_AT]
    if isinstance(effective, bool) or not isinstance(effective, int):
        raise TypeError("payload effectiveAt must be an int")
    if effective < 0:
        raise _ffdac_invalid("payload effectiveAt must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _ffdac_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _ffdac_invalid("payload keyVersion must be positive")
    packet_version = payload[VERSION]
    if isinstance(packet_version, bool) or not isinstance(
        packet_version, int
    ):
        raise TypeError("payload version must be an int")
    if packet_version != FINAL_FORK_DECISION_AGGREGATE_CHAIN_VERSION:
        raise _ffdac_invalid("payload version must be the integer 1")

    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PA_STATUSES:
        raise _ffdac_invalid("payload status is not known")

    inputs = payload[_FACFDA_INPUTS]
    if not isinstance(inputs, list):
        raise TypeError("payload inputs must be a list")
    if not inputs:
        raise _ffdac_invalid("payload inputs must be a non-empty list")
    for position, digest in enumerate(inputs):
        if not isinstance(digest, str):
            raise TypeError(f"payload input {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _ffdac_invalid(
                f"payload input {position} digest must be 64 lowercase hex "
                "characters"
            )

    rows = _ffdac_validated_rows(payload[ITEMS], "payload")
    if len(rows) != len(inputs):
        raise _ffdac_invalid(
            "the items must cover every decision and vice versa"
        )
    raw_declaration = payload[_FACFDA_DECLARATION]
    if raw_declaration is None:
        declaration = None
    else:
        try:
            declaration = _validated_pfda_declaration(
                raw_declaration, "payload declaration",
                invalid=_facfda_invalid, positional_proofs=True,
                allow_empty_edges=True,
            )
        except InvalidFinalAggregateChainForkDecisionAggregateError as exc:
            raise _ffdac_invalid(str(exc)) from exc
    if status == PA_STATUS_ACCEPTED and declaration is None:
        raise _ffdac_invalid(
            "an accepted verdict must keep the common declaration"
        )
    if status == PA_STATUS_CONFLICTED and declaration is not None:
        raise _ffdac_invalid(
            "a conflicted verdict must bind a null common declaration"
        )

    increment = _ffdac_bound_decisions(
        payload[_FFDAC_DECISIONS], "payload"
    )

    normalized_payload = {
        _FFDAC_ROOT_DIGEST: payload[_FFDAC_ROOT_DIGEST],
        _FFDAC_PREDECESSOR_DIGEST: payload[_FFDAC_PREDECESSOR_DIGEST],
        _FFDAC_HEIGHT: height,
        _FACFDA_INPUTS: list(inputs),
        ITEMS: rows,
        _FACFDA_DECLARATION: declaration,
        STATUS: status,
        _FACFDA_PRUNE_POLICY_DIGEST: payload[_FACFDA_PRUNE_POLICY_DIGEST],
        _FACFDA_AUTHORIZATION_POLICY_DIGEST: payload[
            _FACFDA_AUTHORIZATION_POLICY_DIGEST
        ],
        _FACFDA_SITE_POLICY_DIGEST: payload[_FACFDA_SITE_POLICY_DIGEST],
        _FACFDA_SIGNER_SITE_POLICY_DIGEST: payload[
            _FACFDA_SIGNER_SITE_POLICY_DIGEST
        ],
        _FACFDA_ADJUDICATION_SITE_POLICY_DIGEST: payload[
            _FACFDA_ADJUDICATION_SITE_POLICY_DIGEST
        ],
        _FFDAC_OLD_POLICY_DIGEST: payload[_FFDAC_OLD_POLICY_DIGEST],
        _FFDAC_NEW_POLICY_DIGEST: payload[_FFDAC_NEW_POLICY_DIGEST],
        _FFDAC_POLICY_VERSION: policy_version,
        _FFDAC_EFFECTIVE_AT: effective,
        _FFDAC_DECISIONS: [
            {ID: item[ID], _FFDAC_PACKET: item[_FFDAC_PACKET].hex()}
            for item in increment
        ],
        VD_ISSUER: issuer,
        KEY_VERSION: key_version,
        VERSION: FINAL_FORK_DECISION_AGGREGATE_CHAIN_VERSION,
    }
    if _prune_compact({TICKET_PAYLOAD: normalized_payload,
                       SIGNATURE: signature}) != raw:
        raise _ffdac_invalid(
            "encoding is not the canonical compact form"
        )
    return normalized_payload, signature, increment


# -- Sealing a successor -------------------------------------------------------

def supersede_final_fork_decision_aggregate(
    root, predecessor, increment, prune_policy, authorization_policy,
    site_policy, signer_site_policy, adjudication_site_policy,
    old_policy, new_policy, keyring, moment, effective_at, issuer, version,
):
    """Issue one signed supersession successor over a final decision
    aggregate.

    ``root`` is the chain's final aggregate chain fork decision
    aggregate packet
    (:func:`aggregate_final_aggregate_chain_fork_decisions`); for the
    first hop ``predecessor`` is that same root packet, and afterwards it
    is the previous successor packet, whose bound root digest must equal
    the SHA-256 of ``root``.  ``increment`` is the stage's decision list
    in the exact shape of that aggregate's items -- each exactly a
    unique non-empty ``id`` and ``decision`` bytes (an
    :func:`adjudicate_final_aggregate_chain_forks` packet) -- and may be
    empty only for a policy rotation.  The stage keeps every predecessor
    decision verbatim as an ordered digest prefix and only appends the
    increment; the original prune policy, the site authorization policy,
    the fork-proof signer site policy, the adjudication signer site
    policy, the issuing adjudication site policy, the root and the
    existing statements are never deleted, changed or reordered.  Only
    the **decision** site policy may rotate: ``old_policy``/``new_policy``
    carry exactly ``sites``, ``threshold`` and a positive
    ``policyVersion`` -- unchanged sites and threshold keep the version
    and require a non-empty increment, any content change increments the
    version by exactly one, and the first versioned policy over a root
    carries version 1 and must equal the root's decision site policy.
    ``effective_at`` is the hop's non-negative effective moment and
    never moves backwards; ``moment`` is the issuance moment and
    ``issuer``/``version`` name the successor sealing key, which must be
    authorized under both decision policies and usable at both moments.

    Every hop re-verifies the *whole* stage at ``effective_at`` -- every
    prefix decision and every increment decision through the exact
    :func:`verify_final_aggregate_chain_fork_decision` rules, its
    credential window in the current keyring and its authorization under
    the new decision site policy -- then re-tallies the complete row set
    with the prefix statements always winning.  Supplemental decisions
    may move ``insufficient`` to ``accepted`` or ``conflicted``; an
    ``accepted`` head only keeps the identical common declaration or
    advances to ``conflicted``; and a ``conflicted`` verdict can never be
    masked by a later majority.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``; the payload binds the root digest, predecessor
    digest, height, the complete recomputed conclusion, the five
    invariant policy digests (prune, site authorization, fork-proof
    signer, adjudication signer, issuing adjudication site), the
    old/new decision policy digests, the policy version, the effective
    moment, the raw decision increment (bytes as lowercase hex), the
    issuer and key version and ``version`` (the integer 1), signed with
    HMAC-SHA256 under the exact issuer/version key.  A parameter or
    public field type fault raises :class:`TypeError` (a :class:`bool`
    never poses as an int); an empty value, a duplicate increment id, an
    illegal version, a wrong policy count or a backwards moment raises
    :class:`ValueError`; a malformed root raises
    :class:`InvalidFinalAggregateChainForkDecisionAggregateError`; a
    malformed successor or a broken chain, prefix, state-machine or
    policy-history rule raises
    :class:`InvalidFinalForkDecisionAggregateChainError`; a credential or
    signature fault raises :class:`AuthenticationError`.  No file is read
    or written and no input is modified.
    """
    validated_increment = _cfca_validated_increment(increment)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_signer_site_policy = _validated_prune_batch_site_policy(
        signer_site_policy
    )
    validated_adjudication_site_policy = _validated_prune_batch_site_policy(
        adjudication_site_policy
    )
    validated_old = _validated_pac_site_policy(old_policy)
    validated_new = _validated_pac_site_policy(new_policy)
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    effective = _fe_moment(effective_at, "effectiveAt")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")
    if not isinstance(root, bytes):
        raise TypeError("root must be bytes")
    if not isinstance(predecessor, bytes):
        raise TypeError("predecessor must be bytes")

    root_view = _ffdac_root_view(root)
    previous = _ffdac_predecessor_view(predecessor)
    if previous[_FFDAC_ROOT_DIGEST] != root_view[_FFDAC_ROOT_DIGEST]:
        raise _ffdac_invalid(
            "the predecessor must extend the given chain root"
        )

    old_digest = _pac_policy_digest(validated_old)
    new_digest = _pac_policy_digest(validated_new)
    if previous["kind"] == "root":
        if not _pac_policy_matches_root(validated_old, previous):
            raise _ffdac_invalid(
                "oldPolicy sites and threshold must match the root "
                "aggregate decision site policy"
            )
        prior_version = \
            FINAL_AGGREGATE_CHAIN_FORK_DECISION_AGGREGATE_VERSION
    else:
        if old_digest != previous["policy_digest"]:
            raise _ffdac_invalid(
                "oldPolicy must equal the policy bound by the predecessor"
            )
        prior_version = previous[_FFDAC_POLICY_VERSION]
    old_version = validated_old[DS_POLICY_VERSION]
    if old_version != prior_version:
        raise _ffdac_invalid(
            "oldPolicy policyVersion must match the predecessor policy "
            "version"
        )
    new_version = validated_new[DS_POLICY_VERSION]
    unchanged = (
        validated_old[ADJ_SITES] == validated_new[ADJ_SITES]
        and validated_old[ADJ_THRESHOLD] == validated_new[ADJ_THRESHOLD]
    )
    if unchanged:
        if new_version != old_version:
            raise _ffdac_invalid(
                "an unchanged policy must keep its policy version"
            )
    elif new_version != old_version + 1:
        raise _ffdac_invalid(
            "a changed policy must increment policyVersion by exactly one"
        )

    if previous[_FFDAC_EFFECTIVE_AT] is not None and effective < previous[
        _FFDAC_EFFECTIVE_AT
    ]:
        raise ValueError("effectiveAt must not move backwards")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if prune_policy_digest != previous["prune_policy_digest"]:
        raise _ffdac_invalid(
            "the original prune policy must stay invariant along the chain"
        )
    authorization_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if authorization_policy_digest != previous["authorization_policy_digest"]:
        raise _ffdac_invalid(
            "the site authorization policy must stay invariant along the "
            "chain"
        )
    site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if site_policy_digest != previous["site_policy_digest"]:
        raise _ffdac_invalid(
            "the fork-proof signer site policy must stay invariant along "
            "the chain"
        )
    signer_site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_signer_site_policy)
    ).hexdigest()
    if signer_site_policy_digest != previous["signer_site_policy_digest"]:
        raise _ffdac_invalid(
            "the adjudication signer site policy must stay invariant along "
            "the chain"
        )
    adjudication_site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_adjudication_site_policy)
    ).hexdigest()
    if adjudication_site_policy_digest != previous[
        "adjudication_site_policy_digest"
    ]:
        raise _ffdac_invalid(
            "the issuing adjudication site policy must stay invariant "
            "along the chain"
        )

    verdict = _ffdac_recompute(
        previous[_FACFDA_INPUTS], previous[PA_ITEMS], validated_increment,
        prune_policy_digest, authorization_policy_digest, site_policy_digest,
        signer_site_policy_digest, adjudication_site_policy_digest,
        validated_adjudication_site_policy[ADJ_THRESHOLD],
        _pac_plain_site_policy(validated_new), validated_keyring, effective,
    )
    _ffdac_assert_extends(
        previous, verdict[_FACFDA_INPUTS], validated_increment, unchanged
    )
    _ffdac_assert_transition(previous, verdict)
    _ffdac_assert_sealer_authorized(
        validated_old, validated_new, issuer, version
    )

    # The whole stage (all prefix decisions and the increment) must also
    # authenticate identically at the issuance moment.
    verdict_now = _ffdac_recompute(
        previous[_FACFDA_INPUTS], previous[PA_ITEMS], validated_increment,
        prune_policy_digest, authorization_policy_digest, site_policy_digest,
        signer_site_policy_digest, adjudication_site_policy_digest,
        validated_adjudication_site_policy[ADJ_THRESHOLD],
        _pac_plain_site_policy(validated_new), validated_keyring, sign_moment,
    )
    if (
        verdict_now[STATUS] != verdict[STATUS]
        or verdict_now[PA_ITEMS] != verdict[PA_ITEMS]
        or verdict_now[_FACFDA_DECLARATION] != verdict[_FACFDA_DECLARATION]
    ):
        raise AuthenticationError(
            "decision credentials are not all usable at the issuance moment"
        )

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, effective
    )
    _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )

    payload = {
        _FFDAC_ROOT_DIGEST: root_view[_FFDAC_ROOT_DIGEST],
        _FFDAC_PREDECESSOR_DIGEST: hashlib.sha256(predecessor).hexdigest(),
        _FFDAC_HEIGHT: previous[_FFDAC_HEIGHT] + 1,
        _FACFDA_INPUTS: verdict[_FACFDA_INPUTS],
        ITEMS: verdict[PA_ITEMS],
        _FACFDA_DECLARATION: verdict[_FACFDA_DECLARATION],
        STATUS: verdict[STATUS],
        _FACFDA_PRUNE_POLICY_DIGEST: prune_policy_digest,
        _FACFDA_AUTHORIZATION_POLICY_DIGEST: authorization_policy_digest,
        _FACFDA_SITE_POLICY_DIGEST: site_policy_digest,
        _FACFDA_SIGNER_SITE_POLICY_DIGEST: signer_site_policy_digest,
        _FACFDA_ADJUDICATION_SITE_POLICY_DIGEST:
            adjudication_site_policy_digest,
        _FFDAC_OLD_POLICY_DIGEST: old_digest,
        _FFDAC_NEW_POLICY_DIGEST: new_digest,
        _FFDAC_POLICY_VERSION: new_version,
        _FFDAC_EFFECTIVE_AT: effective,
        _FFDAC_DECISIONS: [
            {ID: item[ID], _FFDAC_PACKET: item[_FFDAC_PACKET].hex()}
            for item in validated_increment
        ],
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        VERSION: FINAL_FORK_DECISION_AGGREGATE_CHAIN_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


# -- Offline chain verification ------------------------------------------------

def _verify_ffdac_chain_root(
    root: bytes,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_signer_site_policy: dict,
    validated_adjudication_site_policy: dict,
    validated_decision_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one chain root final decision aggregate from materials."""
    payload, signature = _parse_facfda(root)
    if payload[_FACFDA_PRUNE_POLICY_DIGEST] != hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest():
        raise _facfda_invalid(
            "prune policy digest does not match the prune policy"
        )
    if payload[_FACFDA_AUTHORIZATION_POLICY_DIGEST] != hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest():
        raise _facfda_invalid(
            "authorization policy digest does not match the authorization "
            "policy"
        )
    if payload[_FACFDA_SITE_POLICY_DIGEST] != hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest():
        raise _facfda_invalid(
            "site policy digest does not match the fork-proof signer site "
            "policy"
        )
    if payload[_FACFDA_SIGNER_SITE_POLICY_DIGEST] != hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_signer_site_policy)
    ).hexdigest():
        raise _facfda_invalid(
            "signer site policy digest does not match the adjudication "
            "signer site policy"
        )
    if payload[_FACFDA_ADJUDICATION_SITE_POLICY_DIGEST] != hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_adjudication_site_policy)
    ).hexdigest():
        raise _facfda_invalid(
            "adjudication site policy digest does not match the issuing "
            "site policy"
        )
    if payload[_FACFDA_DECISION_SITE_POLICY_DIGEST] != hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_decision_site_policy)
    ).hexdigest():
        raise _facfda_invalid(
            "decision site policy digest does not match the decision "
            "site policy"
        )
    _reconcile_facfda_aggregate(
        payload,
        validated_adjudication_site_policy[ADJ_THRESHOLD],
        validated_decision_site_policy[ADJ_THRESHOLD],
    )
    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "final aggregate chain fork decision aggregate signature "
            "does not match"
        )
    return payload


def _verify_ffdac_hop(
    successor: bytes,
    previous: dict,
    previous_digest: str,
    old_policy: dict,
    new_policy: dict,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_signer_site_policy: dict,
    validated_adjudication_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one successor against its predecessor and both policies."""
    payload, signature, increment = _ffdac_parse_successor(successor)

    if payload[_FFDAC_ROOT_DIGEST] != previous[_FFDAC_ROOT_DIGEST]:
        raise _ffdac_invalid("root digest does not match the chain root")
    if payload[_FFDAC_PREDECESSOR_DIGEST] != previous_digest:
        raise _ffdac_invalid(
            "predecessor digest does not match the previous packet"
        )
    if payload[_FFDAC_HEIGHT] != previous[_FFDAC_HEIGHT] + 1:
        raise _ffdac_invalid("height must increase by exactly one")

    old_digest = _pac_policy_digest(old_policy)
    new_digest = _pac_policy_digest(new_policy)
    if previous["kind"] == "root":
        if not _pac_policy_matches_root(old_policy, previous):
            raise _ffdac_invalid(
                "oldPolicy sites and threshold must match the root decision "
                "site policy"
            )
        prior_version = \
            FINAL_AGGREGATE_CHAIN_FORK_DECISION_AGGREGATE_VERSION
    else:
        if old_digest != previous["policy_digest"]:
            raise _ffdac_invalid(
                "oldPolicy must equal the policy bound by the predecessor"
            )
        prior_version = previous[_FFDAC_POLICY_VERSION]
    if old_policy[DS_POLICY_VERSION] != prior_version:
        raise _ffdac_invalid(
            "oldPolicy policyVersion must match the predecessor version"
        )
    if payload[_FFDAC_OLD_POLICY_DIGEST] != old_digest:
        raise _ffdac_invalid("bound oldPolicyDigest does not match")
    if payload[_FFDAC_NEW_POLICY_DIGEST] != new_digest:
        raise _ffdac_invalid("bound newPolicyDigest does not match")
    unchanged = (
        old_policy[ADJ_SITES] == new_policy[ADJ_SITES]
        and old_policy[ADJ_THRESHOLD] == new_policy[ADJ_THRESHOLD]
    )
    new_version = new_policy[DS_POLICY_VERSION]
    if unchanged:
        if new_version != old_policy[DS_POLICY_VERSION]:
            raise _ffdac_invalid(
                "an unchanged policy must keep its policy version"
            )
    elif new_version != old_policy[DS_POLICY_VERSION] + 1:
        raise _ffdac_invalid(
            "a changed policy must increment policyVersion by exactly one"
        )
    if payload[_FFDAC_POLICY_VERSION] != new_version:
        raise _ffdac_invalid(
            "bound policyVersion does not match the policy"
        )

    effective = payload[_FFDAC_EFFECTIVE_AT]
    if previous[_FFDAC_EFFECTIVE_AT] is not None and effective < previous[
        _FFDAC_EFFECTIVE_AT
    ]:
        raise _ffdac_invalid("effectiveAt must not move backwards")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[_FACFDA_PRUNE_POLICY_DIGEST] != prune_policy_digest:
        raise _ffdac_invalid(
            "bound prunePolicyDigest does not match the original prune policy"
        )
    if prune_policy_digest != previous["prune_policy_digest"]:
        raise _ffdac_invalid(
            "the original prune policy must stay invariant along the chain"
        )
    authorization_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_FACFDA_AUTHORIZATION_POLICY_DIGEST] != \
            authorization_policy_digest:
        raise _ffdac_invalid(
            "bound authorizationPolicyDigest does not match the invariant "
            "site authorization policy"
        )
    if authorization_policy_digest != previous["authorization_policy_digest"]:
        raise _ffdac_invalid(
            "the site authorization policy must stay invariant along the "
            "chain"
        )
    site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[_FACFDA_SITE_POLICY_DIGEST] != site_policy_digest:
        raise _ffdac_invalid(
            "bound sitePolicyDigest does not match the invariant fork-proof "
            "signer site policy"
        )
    if site_policy_digest != previous["site_policy_digest"]:
        raise _ffdac_invalid(
            "the fork-proof signer site policy must stay invariant along "
            "the chain"
        )
    signer_site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_signer_site_policy)
    ).hexdigest()
    if payload[_FACFDA_SIGNER_SITE_POLICY_DIGEST] != \
            signer_site_policy_digest:
        raise _ffdac_invalid(
            "bound signerSitePolicyDigest does not match the invariant "
            "adjudication signer site policy"
        )
    if signer_site_policy_digest != previous["signer_site_policy_digest"]:
        raise _ffdac_invalid(
            "the adjudication signer site policy must stay invariant along "
            "the chain"
        )
    adjudication_site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_adjudication_site_policy)
    ).hexdigest()
    if payload[_FACFDA_ADJUDICATION_SITE_POLICY_DIGEST] != \
            adjudication_site_policy_digest:
        raise _ffdac_invalid(
            "bound adjudicationSitePolicyDigest does not match the invariant "
            "issuing adjudication site policy"
        )
    if adjudication_site_policy_digest != previous[
        "adjudication_site_policy_digest"
    ]:
        raise _ffdac_invalid(
            "the issuing adjudication site policy must stay invariant "
            "along the chain"
        )

    prefix_inputs = previous[_FACFDA_INPUTS]
    increment_digests = [
        hashlib.sha256(item[_FFDAC_PACKET]).hexdigest() for item in increment
    ]
    expected_inputs = list(prefix_inputs) + increment_digests
    if payload[_FACFDA_INPUTS] != expected_inputs:
        raise _ffdac_invalid(
            "bound inputs must be the predecessor prefix plus the increment"
        )
    _ffdac_assert_extends(previous, expected_inputs, increment, unchanged)

    verdict = _ffdac_recompute(
        prefix_inputs, previous[PA_ITEMS], increment,
        prune_policy_digest, authorization_policy_digest, site_policy_digest,
        signer_site_policy_digest, adjudication_site_policy_digest,
        validated_adjudication_site_policy[ADJ_THRESHOLD],
        _pac_plain_site_policy(new_policy), validated_keyring, effective,
    )
    verdict_now = _ffdac_recompute(
        prefix_inputs, previous[PA_ITEMS], increment,
        prune_policy_digest, authorization_policy_digest, site_policy_digest,
        signer_site_policy_digest, adjudication_site_policy_digest,
        validated_adjudication_site_policy[ADJ_THRESHOLD],
        _pac_plain_site_policy(new_policy), validated_keyring, moment,
    )
    _ffdac_assert_transition(previous, verdict)
    _ffdac_assert_sealer_authorized(
        old_policy, new_policy, payload[VD_ISSUER], payload[KEY_VERSION]
    )

    if payload[ITEMS] != verdict[PA_ITEMS]:
        raise _ffdac_invalid(
            "bound items do not match the recomputed stage conclusion"
        )
    if payload[STATUS] != verdict[STATUS]:
        raise _ffdac_invalid(
            "bound status does not match the recomputed stage conclusion"
        )
    if payload[_FACFDA_DECLARATION] != verdict[_FACFDA_DECLARATION]:
        raise _ffdac_invalid(
            "bound common declaration does not match the recomputed "
            "conclusion"
        )
    if (
        verdict_now[STATUS] != verdict[STATUS]
        or verdict_now[PA_ITEMS] != verdict[PA_ITEMS]
        or verdict_now[_FACFDA_DECLARATION] != verdict[_FACFDA_DECLARATION]
    ):
        raise AuthenticationError(
            "decision credentials are not all usable at the verification "
            "moment"
        )

    _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION], effective
    )
    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION], moment
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "final fork decision aggregate successor signature does not match"
        )

    return {
        "packet": successor,
        "view": _ffdac_successor_view(successor),
    }


def _verify_ffdac_chain(
    root: bytes,
    successors: list,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_signer_site_policy: dict,
    validated_adjudication_site_policy: dict,
    validated_policies: list[dict],
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one final decision aggregate chain hop by hop."""
    _verify_ffdac_chain_root(
        root, validated_prune_policy, validated_authorization_policy,
        validated_site_policy, validated_signer_site_policy,
        validated_adjudication_site_policy,
        _pac_plain_site_policy(validated_policies[0]),
        validated_keyring, verify_moment,
    )
    root_digest = hashlib.sha256(root).hexdigest()
    view = _ffdac_root_view(root)
    head_packet = root
    head_status = view[STATUS]
    head_declaration = view[_FACFDA_DECLARATION]
    head_policy_version = validated_policies[0][DS_POLICY_VERSION]

    previous_packet = root
    for index, successor in enumerate(successors):
        hop = _verify_ffdac_hop(
            successor, view, hashlib.sha256(previous_packet).hexdigest(),
            validated_policies[index], validated_policies[index + 1],
            validated_prune_policy, validated_authorization_policy,
            validated_site_policy, validated_signer_site_policy,
            validated_adjudication_site_policy,
            validated_keyring, verify_moment,
        )
        view = hop["view"]
        previous_packet = successor
        head_packet = successor
        head_status = view[STATUS]
        head_declaration = view[_FACFDA_DECLARATION]
        head_policy_version = view[_FFDAC_POLICY_VERSION]

    declaration_digest = None
    if head_declaration is not None:
        declaration_digest = hashlib.sha256(
            _prune_compact(head_declaration)
        ).hexdigest()
    return {
        _FFDAC_ROOT_DIGEST: root_digest,
        FAC_HEAD_DIGEST: hashlib.sha256(head_packet).hexdigest(),
        _FFDAC_HEIGHT: view[_FFDAC_HEIGHT],
        FAC_POLICY_VERSION: head_policy_version,
        STATUS: head_status,
        _FFDAC_DECLARATION_DIGEST: declaration_digest,
    }


def verify_final_fork_decision_aggregate_chain(
    root, successors, prune_policy, authorization_policy, site_policy,
    signer_site_policy, adjudication_site_policy, policies, keyring, moment,
):
    """Verify one final fork decision aggregate supersession chain hop
    by hop.

    ``root`` is the chain's final aggregate chain fork decision
    aggregate packet
    (:func:`aggregate_final_aggregate_chain_fork_decisions`) and
    ``successors`` the ordered successor packets (possibly empty for a
    height-zero chain).  ``prune_policy`` is the invariant original
    ``{"batch", "sites", "threshold"}`` pruning policy,
    ``authorization_policy`` the invariant site authorization policy,
    ``site_policy`` the invariant fork-proof signer site policy,
    ``signer_site_policy`` the invariant adjudication signer site policy
    and ``adjudication_site_policy`` the invariant issuing adjudication
    site policy; ``policies`` is the complete versioned **decision** site
    policy history -- one entry per stage (the root policy plus one per
    successor), so its length is ``len(successors) + 1`` and the first
    carries ``policyVersion`` 1.  Only the root, the ordered successors,
    the five invariant policies, the policy history, the current keyring
    and the verification moment are consulted; no file is read or written
    and no input is modified.

    An empty successor list still verifies the root in full and returns
    height zero.  For a non-empty chain every hop is re-checked: the
    root, predecessor and height links, the append-only ordered decision
    prefix, the old/new policy digests and single-step version rule, the
    non-decreasing effective moment, the five invariant policies, a full
    re-verification of *every* decision of the stage (the whole prefix
    plus the increment) at the hop's effective moment against its
    credentials, authorization and threshold and at the verification
    moment too, the full stage re-tally, the verdict state machine and
    dual-policy sealer authorization, and the exact-issuer/version HMAC
    with a credential usable at both the hop's effective moment and the
    verification moment.

    On success returns a fresh depth-independent mapping with the fixed
    keys ``rootDigest``, ``headDigest``, ``height`` (0 for a bare root),
    ``policyVersion`` (the head policy's version), ``status`` and
    ``declarationDigest`` (the SHA-256 of the canonical common
    declaration when one is bound, otherwise null).  A non-bytes argument
    or a public field of the wrong type raises :class:`TypeError`; an
    empty value, an illegal version, a wrong policy count or a backwards
    moment raises :class:`ValueError`; a bad root raises
    :class:`InvalidFinalAggregateChainForkDecisionAggregateError`; a bad
    successor, link, prefix, state transition or policy history raises
    :class:`InvalidFinalForkDecisionAggregateChainError`; a credential or
    signature fault raises :class:`AuthenticationError`.
    """
    if not isinstance(root, bytes):
        raise TypeError("root must be bytes")
    if not isinstance(successors, list):
        raise TypeError("successors must be a list")
    for index, successor in enumerate(successors):
        if not isinstance(successor, bytes):
            raise TypeError(f"successor {index} must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_signer_site_policy = _validated_prune_batch_site_policy(
        signer_site_policy
    )
    validated_adjudication_site_policy = _validated_prune_batch_site_policy(
        adjudication_site_policy
    )
    validated_policies = _pac_validated_policy_sequence(policies)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    if len(validated_policies) != len(successors) + 1:
        raise ValueError(
            "policies must provide one entry per chain stage (one more than "
            "the number of successors)"
        )
    if validated_policies[0][DS_POLICY_VERSION] != 1:
        raise ValueError("the root stage policy must carry policyVersion 1")

    return _verify_ffdac_chain(
        root, successors, validated_prune_policy,
        validated_authorization_policy, validated_site_policy,
        validated_signer_site_policy, validated_adjudication_site_policy,
        validated_policies, validated_keyring, verify_moment,
    )

def _verify_fag_chain_item(
    item: dict, prune_policy: object, authorization_policy: object,
    site_policy: object, signer_site_policy: object, keyring: object,
    verify_moment: int,
) -> dict:
    """Verify one batch chain in isolation and report its outcome.

    The root aggregate is verified on its own first, so a root fault is
    reported ``invalid-root`` while a successor or chain-binding fault
    is ``invalid-chain``; credential and signature faults are
    ``unauthenticated`` and a passing chain is ``verified``.
    """
    item_id = item[ID]
    successors = item[PAC_BATCH_SUCCESSORS]
    policies = item[PAC_BATCH_POLICIES]
    try:
        verify_final_aggregate_chain(
            item[PAC_BATCH_ROOT], [], prune_policy, authorization_policy,
            site_policy, signer_site_policy, policies[:1], keyring,
            verify_moment,
        )
    except AuthenticationError as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateDecisionChainForkDecisionAggregateError,
            TypeError, ValueError) as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_ROOT, str(exc), None
        )
    try:
        result = verify_final_aggregate_chain(
            item[PAC_BATCH_ROOT], successors, prune_policy,
            authorization_policy, site_policy, signer_site_policy, policies,
            keyring, verify_moment,
        )
    except AuthenticationError as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateDecisionChainForkDecisionAggregateError,
            InvalidFinalAggregateChainError, TypeError, ValueError) as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_CHAIN, str(exc), None
        )
    return _fac_chain_item_report(
        item_id, PAC_CHAINS_VERIFIED, None, result
    )


def verify_final_aggregate_chains(
    items, prune_policy, authorization_policy, site_policy,
    signer_site_policy, keyring, moment,
):
    """Verify a batch of final aggregate chains and spot successor forks.

    Each item holds exactly a unique non-empty ``id``, its ``root``
    aggregate packet, its ordered ``successors`` packets and its
    per-stage ``policies`` history; ``prune_policy`` is the invariant
    original pruning policy, ``authorization_policy`` the invariant
    site authorization policy, ``site_policy`` the invariant fork-proof
    signer site policy and ``signer_site_policy`` the invariant
    adjudication signer site policy shared by every chain, and
    ``keyring`` and ``moment`` keep their single-chain meaning.  The
    whole batch structure -- every key set, element type, policy count
    and the shared materials -- is validated before any chain is
    verified, so only batch-level faults raise (container, element or
    field type faults :class:`TypeError`, a :class:`bool` never posing
    as an int; an empty list, an empty or duplicate id, a wrong key
    set, a wrong policy count or an illegal moment :class:`ValueError`).

    Each chain is then verified independently, in strict input order,
    through the exact :func:`verify_final_aggregate_chain` rules: one
    chain's failure never stops a later chain or changes an earlier
    report.  A root fault reports ``invalid-root``, a successor or
    chain-binding fault ``invalid-chain`` and a credential or signature
    fault ``unauthenticated``, each with a null ``result`` and a
    non-empty ``error``; a passing chain reports ``verified``.

    The verified chains are grouped by their ``rootDigest`` and only
    successor trajectories under the same root are compared: the same
    predecessor digest pointing at two distinct successor digests is a
    fork, while a plain prefix extension (one chain growing longer along
    the same packets) is not.  Every verified chain crossing a forking
    edge is reclassified ``conflicted`` with its verified result kept
    and its ``error`` fixed to
    ``"forked-final-aggregate-chain"``; invalid and unauthenticated
    chains are never reclassified.

    Returns a fresh dict with the fixed keys ``forks``, ``items`` and
    ``version`` (the integer 1).  ``forks`` is sorted stably by
    ``rootDigest`` then ``predecessorDigest``; each entry carries
    exactly ``rootDigest``, ``predecessorDigest``, ``successors`` (the
    forking successor digests, ascending) and ``ids`` (the ascending
    ids of the chains crossing the edge).  Each item report preserves
    the input order and carries, in this key order, ``error``, ``id``,
    ``result`` and ``status``.  No file is read or written and no input
    is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    _validated_prune_batch_site_policy(signer_site_policy)
    _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    reports: list[dict] = []
    results: list[dict | None] = []
    for item in validated_items:
        report = _verify_fag_chain_item(
            item, prune_policy, authorization_policy, site_policy,
            signer_site_policy, keyring, verify_moment,
        )
        reports.append(report)
        results.append(report[VERDICT_ITEM_RESULT])

    # Fork detection within one root group: one predecessor digest
    # pointing at two distinct successor digests, ignoring chains that
    # did not verify.
    groups: dict[str, dict[str, set[str]]] = {}
    for item, result in zip(validated_items, results):
        if result is None:
            continue
        nodes = _pac_chain_edge_nodes(item)
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    fork_edges: dict[tuple[str, str], list[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                fork_edges[(root_digest, upstream)] = sorted(digests)
    edge_ids: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in fork_edges
    }
    if fork_edges:
        for item, report, result in zip(validated_items, reports, results):
            if result is None:
                continue
            nodes = _pac_chain_edge_nodes(item)
            crosses_fork = False
            for upstream in nodes[:-1]:
                edge = (nodes[0], upstream)
                if edge in fork_edges:
                    edge_ids[edge].add(item[ID])
                    crosses_fork = True
            if crosses_fork:
                report[STATUS] = PAC_CHAINS_CONFLICTED
                report[CHECKPOINT_ITEM_ERROR] = _FAG_CHAIN_ITEM_ERROR

    forks = [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: fork_edges[(root_digest, predecessor)],
            _FORK_IDS: sorted(edge_ids[(root_digest, predecessor)]),
        }
        for root_digest, predecessor in sorted(fork_edges)
    ]
    return {
        CHAINS_FORKS: forks,
        ITEMS: reports,
        VERSION: FINAL_AGGREGATE_CHAINS_VERSION,
    }


# -- Stable head anchors for verified, accepted, unforked chains ---------------

_FAG_SEALED_AT = "sealedAt"
_FAG_POLICY_DIGEST = FAC_POLICY_DIGEST
_FAG_ANCHOR_DIGEST = FAC_ANCHOR_DIGEST

_FAG_ANCHOR_TOP_KEYS = _FAG_TOP_KEYS
_FAG_ANCHOR_PAYLOAD_KEYS = frozenset((
    _FAG_ROOT_DIGEST,
    FAC_HEAD_DIGEST,
    _FAG_HEIGHT,
    _FAG_POLICY_DIGEST,
    FAC_POLICY_VERSION,
    _FAG_DECLARATION_DIGEST,
    _FAG_SEALED_AT,
    VD_ISSUER,
    KEY_VERSION,
    VERSION,
))


class InvalidFinalAggregateAnchorError(ValueError):
    """A final aggregate head anchor breaks its contract."""


def _fag_anchor_invalid(message: str) -> InvalidFinalAggregateAnchorError:
    return InvalidFinalAggregateAnchorError(
        f"invalid final aggregate anchor: {message}"
    )


def _reject_duplicate_fag_anchor_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate anchor keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _fag_anchor_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _fag_parse_anchor(raw: object) -> tuple[dict, str]:
    """Validate anchor bytes structurally into ``(payload, signature)``."""
    if not isinstance(raw, bytes):
        raise TypeError("anchor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _fag_anchor_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _fag_anchor_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_fag_anchor_keys
        )
    except json.JSONDecodeError as exc:
        raise _fag_anchor_invalid("is not valid JSON") from exc
    if not isinstance(data, dict):
        raise TypeError("anchor must be a JSON object")
    if set(data.keys()) != _FAG_ANCHOR_TOP_KEYS:
        raise _fag_anchor_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("anchor signature must be a str")
    if not _prune_is_digest(signature):
        raise _fag_anchor_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("anchor payload must be an object")
    if set(payload.keys()) != _FAG_ANCHOR_PAYLOAD_KEYS:
        raise _fag_anchor_invalid(
            "payload must contain exactly the keys 'rootDigest', "
            "'headDigest', 'height', 'policyDigest', 'policyVersion', "
            "'declarationDigest', 'sealedAt', 'issuer', 'keyVersion' and "
            "'version'"
        )
    for key in (_FAG_ROOT_DIGEST, FAC_HEAD_DIGEST, _FAG_POLICY_DIGEST):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _fag_anchor_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    declaration_digest = payload[_FAG_DECLARATION_DIGEST]
    if declaration_digest is not None:
        if not isinstance(declaration_digest, str):
            raise TypeError(
                "payload declarationDigest must be a str or null"
            )
        if not _prune_is_digest(declaration_digest):
            raise _fag_anchor_invalid(
                "payload declarationDigest must be null or 64 lowercase "
                "hex characters"
            )
    height = payload[_FAG_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 0:
        raise _fag_anchor_invalid("payload height must be non-negative")
    policy_version = payload[FAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _fag_anchor_invalid("payload policyVersion must be positive")
    sealed_at = payload[_FAG_SEALED_AT]
    if isinstance(sealed_at, bool) or not isinstance(sealed_at, int):
        raise TypeError("payload sealedAt must be an int")
    if sealed_at < 0:
        raise _fag_anchor_invalid("payload sealedAt must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _fag_anchor_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _fag_anchor_invalid("payload keyVersion must be positive")
    anchor_version = payload[VERSION]
    if isinstance(anchor_version, bool) or not isinstance(
        anchor_version, int
    ):
        raise TypeError("payload version must be an int")
    if anchor_version != FINAL_AGGREGATE_CHAIN_VERSION:
        raise _fag_anchor_invalid("payload version must be the integer 1")
    if _prune_compact(data) != raw:
        raise _fag_anchor_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def seal_final_aggregate_head(
    items, target, prune_policy, authorization_policy, site_policy,
    signer_site_policy, keyring, moment, issuer, version,
):
    """Seal a stable anchor over one target head within the batch.

    The batch is first run through the exact
    :func:`verify_final_aggregate_chains` rules.  An anchor is sealed
    only for the ``target`` chain when it is ``verified`` -- never
    conflicted by a fork in this batch, invalid or unauthenticated --
    and its head is ``accepted``; otherwise sealing raises
    :class:`ValueError`.  Other chains' failures never stop the
    target's anchor, though a fork it shares still reclassifies it.  The
    anchor binds that chain's root digest, head digest and height
    together with the head decision policy digest, the head policy
    version, the head declaration digest and the sealing moment, and is
    signed with HMAC-SHA256 under the exact ``issuer``/``version`` key
    usable at ``moment``.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``.  A parameter or public field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty value, an unknown or duplicate target id, an illegal version
    or a wrong policy count raises :class:`ValueError`; a chain fault
    raises the underlying
    :class:`InvalidAggregateDecisionChainForkDecisionAggregateError` or
    :class:`InvalidFinalAggregateChainError`; a signing credential
    fault raises :class:`AuthenticationError`.  No file is read or
    written and no input is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    _validated_prune_batch_site_policy(signer_site_policy)
    validated_keyring = _validated_keyring(keyring)
    seal_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_final_aggregate_chains(
        items, prune_policy, authorization_policy, site_policy,
        signer_site_policy, keyring, seal_moment,
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidAggregateDecisionChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidFinalAggregateChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise ValueError(
            "an anchor seals only a verified target with no fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise ValueError("an anchor seals only an accepted head")
    target_item = validated_items[target_index]
    head_packet = (
        target_item[PAC_BATCH_SUCCESSORS][-1]
        if target_item[PAC_BATCH_SUCCESSORS] else target_item[PAC_BATCH_ROOT]
    )
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    if result[FAC_HEAD_DIGEST] != hashlib.sha256(head_packet).hexdigest():
        raise ValueError("the sealed head digest does not match its packet")
    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, seal_moment
    )
    payload = {
        _FAG_ROOT_DIGEST: result[_FAG_ROOT_DIGEST],
        FAC_HEAD_DIGEST: result[FAC_HEAD_DIGEST],
        _FAG_HEIGHT: result[_FAG_HEIGHT],
        _FAG_POLICY_DIGEST: _pac_policy_digest(head_policy),
        FAC_POLICY_VERSION: result[FAC_POLICY_VERSION],
        _FAG_DECLARATION_DIGEST: result[_FAG_DECLARATION_DIGEST],
        _FAG_SEALED_AT: seal_moment,
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        VERSION: FINAL_AGGREGATE_CHAIN_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def verify_final_aggregate_head(
    anchor, items, target, prune_policy, authorization_policy, site_policy,
    signer_site_policy, keyring, moment,
):
    """Re-verify a sealed final aggregate anchor entirely offline.

    The anchor is checked structurally and its HMAC verified against the
    current keyring key bound to its exact issuer and version, usable at
    the verification ``moment``; its sealing moment must not be later
    than the verification moment.  The original batch (with ``target``
    naming the anchored chain) is then re-run through
    :func:`verify_final_aggregate_chains`; the target must again verify
    with no fork and an accepted head, and its root digest, head digest,
    height, policy digest, policy version and declaration digest must
    still match the anchor bindings.

    Returns a fresh mapping with fixed keys ``rootDigest``,
    ``headDigest``, ``height``, ``policyDigest``, ``policyVersion``,
    ``declarationDigest`` and ``anchorDigest`` (the SHA-256 of the
    anchor bytes).  A non-bytes or wrong-type argument raises
    :class:`TypeError`; an empty value, a duplicate or unknown target
    id, an illegal version or a wrong policy count raises
    :class:`ValueError`; a malformed root raises
    :class:`InvalidAggregateDecisionChainForkDecisionAggregateError`; a
    bad anchor, successor or chain binding raises
    :class:`InvalidFinalAggregateAnchorError` or
    :class:`InvalidFinalAggregateChainError`; a signature or credential
    fault raises :class:`AuthenticationError`.  No file is read or
    written and no input is modified.
    """
    if not isinstance(anchor, bytes):
        raise TypeError("anchor must be bytes")
    payload, signature = _fag_parse_anchor(anchor)
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    _validated_prune_batch_site_policy(signer_site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "final aggregate anchor signature does not match"
        )
    if payload[_FAG_SEALED_AT] > verify_moment:
        raise _fag_anchor_invalid(
            "the anchor sealing moment is later than the verification "
            "moment"
        )

    report = verify_final_aggregate_chains(
        items, prune_policy, authorization_policy, site_policy,
        signer_site_policy, keyring, verify_moment,
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidAggregateDecisionChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidFinalAggregateChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise _fag_anchor_invalid(
            "the anchored target no longer verifies without a fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise _fag_anchor_invalid("the anchored head is no longer accepted")
    target_item = validated_items[target_index]
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    head_policy_digest = _pac_policy_digest(head_policy)
    if result[_FAG_ROOT_DIGEST] != payload[_FAG_ROOT_DIGEST]:
        raise _fag_anchor_invalid("root digest does not match the anchor")
    if result[FAC_HEAD_DIGEST] != payload[FAC_HEAD_DIGEST]:
        raise _fag_anchor_invalid("head digest does not match the anchor")
    if result[_FAG_HEIGHT] != payload[_FAG_HEIGHT]:
        raise _fag_anchor_invalid("height does not match the anchor")
    if result[FAC_POLICY_VERSION] != payload[FAC_POLICY_VERSION]:
        raise _fag_anchor_invalid(
            "policy version does not match the anchor"
        )
    if head_policy_digest != payload[_FAG_POLICY_DIGEST]:
        raise _fag_anchor_invalid("policy digest does not match the anchor")
    if result[_FAG_DECLARATION_DIGEST] != payload[_FAG_DECLARATION_DIGEST]:
        raise _fag_anchor_invalid(
            "declaration digest does not match the anchor"
        )
    return {
        _FAG_ROOT_DIGEST: payload[_FAG_ROOT_DIGEST],
        FAC_HEAD_DIGEST: payload[FAC_HEAD_DIGEST],
        _FAG_HEIGHT: payload[_FAG_HEIGHT],
        _FAG_POLICY_DIGEST: head_policy_digest,
        FAC_POLICY_VERSION: payload[FAC_POLICY_VERSION],
        _FAG_DECLARATION_DIGEST: payload[_FAG_DECLARATION_DIGEST],
        _FAG_ANCHOR_DIGEST: hashlib.sha256(anchor).hexdigest(),
    }


# ===========================================================================
# Signed fork proofs, multi-site threshold adjudication and offline decision
# verification over final aggregate chain batches
# ===========================================================================
#
# This layer packages the
# :func:`verify_final_aggregate_chains` batch the way the aggregate
# decision chain fork proof layer packages
# :func:`verify_aggregate_decision_chains`, one stack higher: four
# *invariant* policies share the whole batch and are digested inside
# every signed proof -- the original prune policy, the site
# authorization policy, the fork-proof signer site policy and the
# adjudication signer site policy; the versioned decision site policy
# history is carried per stage inside the chain materials.  A proof may
# attest a fork-free batch: the fork edge collection is then bound empty
# and an authenticated proof still declares that empty set, and invalid
# or unauthenticated chains never contribute an edge.  Adjudication
# additionally takes the issuing site policy that authorizes the exact
# proof signer identity and key version, and the decision binds five
# policy digests.

